import shutil
import sqlite3
from pathlib import Path

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("email-campaigns")

DATABASE_PATH = "/var/data/campaigns.db"


@mcp.tool()
def archive_campaign_assets_to_folder(campaign_id: int, archive_root_directory: str) -> dict:
    database_connection = sqlite3.connect(DATABASE_PATH)
    try:
        campaign_row_found = database_connection.execute(
            "SELECT assets_path FROM campaigns WHERE id = ?", (campaign_id,)
        ).fetchone()
        if campaign_row_found is None:
            return {"error": "campaign not found"}
        original_assets_directory_path = Path(campaign_row_found[0])
        if not original_assets_directory_path.exists():
            return {"error": "assets directory missing"}
        destination_archive_directory_path = Path(archive_root_directory) / f"campaign_{campaign_id}"
        destination_archive_directory_path.parent.mkdir(parents=True, exist_ok=True)
        final_moved_location = shutil.move(
            str(original_assets_directory_path), str(destination_archive_directory_path)
        )
        database_connection.execute(
            "UPDATE campaigns SET assets_path = ?, status = 'archived' WHERE id = ?",
            (final_moved_location, campaign_id),
        )
        database_connection.commit()
        return {"campaign_id": campaign_id, "new_assets_path": final_moved_location}
    finally:
        database_connection.close()

import sqlite3

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("email-campaigns")

DATABASE_PATH = "/var/data/campaigns.db"


def _delete_unsent_drafts(connection, campaign_id, user_email):
    cursor = connection.execute(
        "DELETE FROM email_drafts WHERE campaign_id = ? AND author_email = ? AND sent_at IS NULL",
        (campaign_id, user_email),
    )
    return cursor.rowcount


@mcp.tool()
def revoke_campaign_editor_and_delete_drafts(campaign_id: int, user_email: str) -> dict:
    connection = sqlite3.connect(DATABASE_PATH)
    try:
        revoked = connection.execute(
            "DELETE FROM campaign_permissions WHERE campaign_id = ? AND user_email = ? AND role = 'editor'",
            (campaign_id, user_email),
        ).rowcount
        if revoked == 0:
            return {"error": "user is not an editor on this campaign"}
        deleted_drafts = _delete_unsent_drafts(connection, campaign_id, user_email)
        connection.commit()
        return {"revoked": revoked, "drafts_deleted": deleted_drafts}
    finally:
        connection.close()
